class Solution {
    public TreeNode trimBST(TreeNode root, int low, int high) {
        while (root != null && (root.val < low || root.val > high)) {
            root = root.val < low ? root.right : root.left;
        }
        if (root == null) {
            return null;
        }

        TreeNode node = root;
        while (node != null) {
            while (node.left != null && node.left.val < low) {
                node.left = node.left.right;
            }
            node = node.left;
        }

        node = root;
        while (node != null) {
            while (node.right != null && node.right.val > high) {
                node.right = node.right.left;
            }
            node = node.right;
        }
        return root;
    }
}

class Solution {
    public TreeNode trimBST(TreeNode root, int low, int high) {
        while (root != null && (root.val < low || root.val > high)) {
            root = root.val < low ? root.right : root.left;
        }
        if (root == null) {
            return null;
        }

        java.util.Deque<TreeNode> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();

            while (node.left != null && node.left.val < low) {
                node.left = node.left.right;
            }
            while (node.right != null && node.right.val > high) {
                node.right = node.right.left;
            }

            if (node.left != null) {
                stack.push(node.left);
            }
            if (node.right != null) {
                stack.push(node.right);
            }
        }
        return root;
    }
}

class Solution {
    public TreeNode trimBST(TreeNode root, int low, int high) {
        if (root == null) {
            return null;
        }
        if (root.val < low) {
            return trimBST(root.right, low, high);
        }
        if (root.val > high) {
            return trimBST(root.left, low, high);
        }

        TreeNode kept = new TreeNode(root.val);
        kept.left = trimBST(root.left, low, high);
        kept.right = trimBST(root.right, low, high);
        return kept;
    }
}
